var TEXT_MAP = {
  title: '一元二次方程求根公式',
  eq_2: '2',
  eq_x2: 'x²',
  eq_minus: ' − ',
  eq_b: '−7',
  eq_x: 'x',
  eq_plus: ' + ',
  eq_3: '3',
  eq_eq0: ' = 0',
  legend_a: 'a = 2',
  legend_b: 'b = −7',
  legend_c: 'c = 3',
  legend_note: '颜色对应：红色 a，蓝色 b，绿色 c',
  formula_title: '求根公式',
  fm_x_eq: 'x =',
  fm_minus: '−',
  fm_b: 'b',
  fm_pm_sqrt: ' ± √(',
  fm_b2: 'b²',
  fm_minus4: ' − 4',
  fm_a: 'a',
  fm_c: 'c',
  fm_close: ')',
  fm_2: '2',
  fm_delta_mark: 'Δ',
  disc_title: '判别式',
  disc_delta: 'Δ = ',
  disc_b2: 'b²',
  disc_minus4: ' − 4',
  disc_a: 'a',
  disc_c: 'c',
  disc_eq25: ' = 25',
  disc_sub: 'b² = 49，4ac = 24，Δ = 25'
};
var KEY_ORDER = ['title','eq_2','eq_x2','eq_minus','eq_b','eq_x','eq_plus','eq_3','eq_eq0','legend_a','legend_b','legend_c','legend_note','formula_title','fm_x_eq','fm_minus','fm_b','fm_pm_sqrt','fm_b2','fm_minus4','fm_a','fm_c','fm_close','fm_2','fm_delta_mark','disc_title','disc_delta','disc_b2','disc_minus4','disc_a','disc_c','disc_eq25','disc_sub'];
var visual = {
  prepare: function (input) {
    var out = [];
    for (var i = 0; i < KEY_ORDER.length; i++) {
      out.push({ kind: 'text', payload: TEXT_MAP[KEY_ORDER[i]] });
    }
    return out;
  },
  render: function (input, metrics) {
    var W = (input.viewport && input.viewport.widthDu) || 960;
    var H = (input.viewport && input.viewport.heightDu) || 640;
    var METRICS = {};
    for (var mi = 0; mi < KEY_ORDER.length; mi++) {
      METRICS[KEY_ORDER[mi]] = (metrics && metrics[mi]) ? metrics[mi] : null;
    }
    function estimateWidth(s, fs) {
      var w = 0;
      for (var i = 0; i < s.length; i++) {
        var ch = s.charAt(i);
        var code = s.charCodeAt(i);
        if (code > 255) w += fs * 0.95;
        else if (ch === ' ') w += fs * 0.3;
        else if ('ilI.,;:!|'.indexOf(ch) >= 0) w += fs * 0.28;
        else if (ch === '²') w += fs * 0.5;
        else if ('MW@'.indexOf(ch) >= 0) w += fs * 0.9;
        else w += fs * 0.6;
      }
      return w;
    }
    function textWidth(key, fs) {
      var s = TEXT_MAP[key] || '';
      var est = estimateWidth(s, fs);
      var m = METRICS[key];
      var mw = m && (m.width || m.advance || m.w);
      if (mw) est = Math.max(est, mw * (fs / 18));
      return est;
    }
    function totalWidth(pieces, fs) {
      var t = 0;
      for (var i = 0; i < pieces.length; i++) t += textWidth(pieces[i].k, fs);
      return t;
    }
    var paths = [];
    var children = [];
    var pid = 0;
    function addPath(commands, stroke, fill, strokeWidth) {
      var id = 'p' + pid;
      pid += 1;
      paths.push({ id: id, commands: commands });
      var node = { type: 'path', pathId: id };
      if (stroke) node.stroke = stroke;
      if (fill) node.fill = fill;
      if (strokeWidth) node.strokeWidth = strokeWidth;
      children.push(node);
    }
    function addLabel(key, x, y, opts) {
      var o = opts || {};
      var node = {
        type: 'label',
        text: TEXT_MAP[key],
        x: x,
        y: y,
        fontSize: o.fontSize || 18,
        fill: o.fill || '#1f2d3d',
        textAnchor: o.textAnchor || 'start'
      };
      if (o.fontWeight) node.fontWeight = o.fontWeight;
      children.push(node);
    }
    function rect(x, y, w, h) {
      return visualSdk.polyline([[x, y], [x + w, y], [x + w, y + h], [x, y + h], [x, y]]);
    }
    function layoutPieces(pieces, centerX, baseline, fs) {
      var total = totalWidth(pieces, fs);
      var x = centerX - total / 2;
      var out = {};
      for (var i = 0; i < pieces.length; i++) {
        var p = pieces[i];
        var w = textWidth(p.k, fs);
        out[p.k] = { x: x, w: w, baseline: baseline, fs: fs };
        var opts = {
          fontSize: fs,
          fill: p.color || '#1f2d3d',
          textAnchor: 'start'
        };
        if (p.bold) opts.fontWeight = 'bold';
        addLabel(p.k, x, baseline, opts);
        x += w;
      }
      return out;
    }
    function underline(layoutItem, color, dy, sw) {
      if (!layoutItem) return null;
      var x1 = layoutItem.x + 2;
      var x2 = layoutItem.x + layoutItem.w - 2;
      var y = layoutItem.baseline + (dy || 10);
      addPath(visualSdk.polyline([[x1, y], [x2, y]]), color, null, sw || 3);
      addPath(visualSdk.polyline([[x1, y - 4], [x1, y + 4]]), color, null, 2);
      addPath(visualSdk.polyline([[x2, y - 4], [x2, y + 4]]), color, null, 2);
      return { x1: x1, x2: x2, y: y, cx: (x1 + x2) / 2 };
    }

    addLabel('title', W / 2, 44, { fontSize: 26, fill: '#17263a', textAnchor: 'middle', fontWeight: 'bold' });

    var eqPieces = [
      { k: 'eq_2', color: '#c0392b' },
      { k: 'eq_x2', color: '#1f2d3d' },
      { k: 'eq_minus', color: '#1f2d3d' },
      { k: 'eq_b', color: '#1f5fa8' },
      { k: 'eq_x', color: '#1f2d3d' },
      { k: 'eq_plus', color: '#1f2d3d' },
      { k: 'eq_3', color: '#1e8449' },
      { k: 'eq_eq0', color: '#1f2d3d' }
    ];
    var eqLayout = layoutPieces(eqPieces, W / 2, 112, 30);
    var markColors = { a: '#c0392b', b: '#1f5fa8', c: '#1e8449' };
    var marks = {};
    marks.a = underline(eqLayout.eq_2, markColors.a, 12, 3);
    marks.b = underline(eqLayout.eq_b, markColors.b, 12, 3);
    marks.c = underline(eqLayout.eq_3, markColors.c, 12, 3);

    var legendW = 170;
    var legendH = 44;
    var legendGap = 24;
    var legendStart = (W - (3 * legendW + 2 * legendGap)) / 2;
    var legendY = 170;
    var legends = [
      { key: 'legend_a', color: '#c0392b', bg: '#fff4f2', mark: 'a' },
      { key: 'legend_b', color: '#1f5fa8', bg: '#f2f7ff', mark: 'b' },
      { key: 'legend_c', color: '#1e8449', bg: '#f1fbf4', mark: 'c' }
    ];
    for (var li = 0; li < legends.length; li++) {
      var lg = legends[li];
      var lx = legendStart + li * (legendW + legendGap);
      addPath(rect(lx, legendY, legendW, legendH), lg.color, lg.bg, 2);
      addLabel(lg.key, lx + legendW / 2, legendY + 29, {
        fontSize: 20,
        fill: lg.color,
        textAnchor: 'middle',
        fontWeight: 'bold'
      });
      var target = marks[lg.mark];
      if (target) {
        addPath(visualSdk.arrow(lx + legendW / 2, legendY, target.cx, target.y + 7, {}), lg.color, 'none', 1.5);
      }
    }
    addLabel('legend_note', W / 2, 232, { fontSize: 16, fill: '#5b6b7f', textAnchor: 'middle' });

    var cardX = 110;
    var cardY = 250;
    var cardW = 740;
    var cardH = 200;
    addPath(rect(cardX, cardY, cardW, cardH), '#c9d3e0', '#fbfcff', 2);
    addLabel('formula_title', cardX + 30, cardY + 32, { fontSize: 22, fill: '#1f2d3d', fontWeight: 'bold' });

    var numPieces = [
      { k: 'fm_minus', color: '#1f2d3d' },
      { k: 'fm_b', color: '#1f5fa8' },
      { k: 'fm_pm_sqrt', color: '#1f2d3d' },
      { k: 'fm_b2', color: '#1f5fa8' },
      { k: 'fm_minus4', color: '#1f2d3d' },
      { k: 'fm_a', color: '#c0392b' },
      { k: 'fm_c', color: '#1e8449' },
      { k: 'fm_close', color: '#1f2d3d' }
    ];
    var numLayout = layoutPieces(numPieces, 550, 330, 28);
    var denPieces = [
      { k: 'fm_2', color: '#1f2d3d' },
      { k: 'fm_a', color: '#c0392b' }
    ];
    layoutPieces(denPieces, 550, 418, 28);
    var numTotal = totalWidth(numPieces, 28);
    var barHalf = Math.max(numTotal / 2 + 16, 80);
    var barX1 = 550 - barHalf;
    var barX2 = 550 + barHalf;
    addPath(visualSdk.polyline([[barX1, 378], [barX2, 378]]), '#1f2d3d', null, 2);
    addLabel('fm_x_eq', barX1 - 92, 380, { fontSize: 30, fill: '#1f2d3d', textAnchor: 'start' });
    var d1 = numLayout.fm_b2;
    var d2 = numLayout.fm_c;
    if (d1 && d2) {
      var bx1 = d1.x - 2;
      var bx2 = d2.x + d2.w + 2;
      addPath(visualSdk.polyline([[bx1, 348], [bx1, 353], [bx2, 353], [bx2, 348]]), '#b36b00', null, 1.5);
      addLabel('fm_delta_mark', (bx1 + bx2) / 2, 369, { fontSize: 15, fill: '#b36b00', textAnchor: 'middle', fontWeight: 'bold' });
    }

    var discX = 110;
    var discY = 465;
    var discW = 740;
    var discH = 130;
    addPath(rect(discX, discY, discW, discH), '#e8c99b', '#fffaf2', 2);
    addLabel('disc_title', discX + 30, discY + 32, { fontSize: 22, fill: '#9a5b00', fontWeight: 'bold' });
    var discPieces = [
      { k: 'disc_delta', color: '#9a5b00' },
      { k: 'disc_b2', color: '#1f5fa8' },
      { k: 'disc_minus4', color: '#1f2d3d' },
      { k: 'disc_a', color: '#c0392b' },
      { k: 'disc_c', color: '#1e8449' },
      { k: 'disc_eq25', color: '#8e44ad' }
    ];
    layoutPieces(discPieces, 550, 535, 26);
    addLabel('disc_sub', 550, 575, { fontSize: 18, fill: '#5b6b7f', textAnchor: 'middle' });

    return {
      schemaVersion: 1,
      sceneId: 'quadratic-formula-transcription',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: paths,
      root: { type: 'group', children: children }
    };
  }
};
